export const createCustomer = async ({ name, email }: { name: string; email: string }) => {
    const stripe = createStripeClient();
    return stripe.customers.create({ name, email });
};

export const isTierUpgrade = (currentPrice: Price, newPrice: Price) => {
    return newPrice.monthlyMessageLimit > currentPrice.monthlyMessageLimit;
};

export const createCheckoutSession = async ({
    priceId,
    userId,
    stripeCustomerId,
    successUrl,
    cancelUrl,
    existing,
}: {
    priceId: string;
    userId: string;
    stripeCustomerId: string;
    existing?: {
        subscriptionId: string;
        customerId: string;
    };
    successUrl: string;
    cancelUrl: string;
}) => {
    const stripe = createStripeClient();
    let session: Stripe.Checkout.Session;
    if (existing) {
        session = await stripe.checkout.sessions.create({
            mode: 'subscription',
            customer: stripeCustomerId,
            line_items: [
                {
                    price: priceId,
                    quantity: 1,
                },
            ],
            payment_method_types: ['card'],
            metadata: {
                user_id: userId,
            },
            allow_promotion_codes: true,
            success_url: successUrl,
            cancel_url: cancelUrl,
            subscription_data: {
                proration_behavior: 'create_prorations',
            },
        });
    } else {
        session = await stripe.checkout.sessions.create({
            mode: 'subscription',
            customer: stripeCustomerId,
            line_items: [
                {
                    price: priceId,
                    quantity: 1,
                },
            ],
            payment_method_types: ['card'],
            metadata: {
                user_id: userId,
            },
            allow_promotion_codes: true,
            success_url: successUrl,
            cancel_url: cancelUrl,
        });
    }
    return session;
};

export const createBillingPortalSession = async ({
    customerId,
    returnUrl,
}: {
    customerId: string;
    returnUrl: string;
}) => {
    const stripe = createStripeClient();
    return await stripe.billingPortal.sessions.create({
        customer: customerId,
        return_url: returnUrl,
    });
};

export const updateSubscription = async ({
    subscriptionId,
    subscriptionItemId,
    priceId,
}: {
    subscriptionId: string;
    subscriptionItemId: string;
    priceId: string;
}) => {
    const stripe = createStripeClient();
    return stripe.subscriptions.update(subscriptionId, {
        items: [
            {
                id: subscriptionItemId,
                price: priceId,
            },
        ],
        proration_behavior: 'always_invoice',
    });
};

export const updateSubscriptionNextPeriod = async ({
    subscriptionId,
    priceId,
}: {
    subscriptionId: string;
    priceId: string;
}) => {
    const stripe = createStripeClient();

    // Step 1: Create a subscription schedule from the current subscription
    const schedule = await stripe.subscriptionSchedules.create({
        from_subscription: subscriptionId,
